import{_ as t,a,o as r,a6 as s}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse(`{"title":"Delete a GDPR Request","description":"","frontmatter":{"outline":false,"examples":[{"id":"delete-gdpr-request","title":"Delete a GDPR Request","description":"Remove a GDPR data request record owned by the authenticated customer.","query":"mutation DeleteGdprRequest($id: ID!) {\\n  deleteGdprRequest(\\n    input: {\\n      id: $id\\n    }\\n  ) {\\n    gdprRequest {\\n      _id\\n      successMessage\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"id\\": \\"/api/shop/gdpr-requests/12\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"deleteGdprRequest\\": {\\n      \\"gdprRequest\\": {\\n        \\"_id\\": 12,\\n        \\"successMessage\\": \\"Your GDPR data request has been deleted successfully.\\"\\n      }\\n    }\\n  }\\n}\\n","commonErrors":[{"error":"GDPR disabled","cause":"GDPR data requests are turned off in the store's admin configuration","solution":"Re-enable GDPR from the admin configuration before deleting a request"},{"error":"NOT_FOUND","cause":"The request does not exist or is not owned by the authenticated customer","solution":"Only request IDs belonging to the logged-in customer can be deleted"},{"error":"UNAUTHENTICATED","cause":"Missing or invalid customer Bearer token","solution":"Log in and provide a valid customer authentication token"}]}]},"headers":[],"relativePath":"api/graphql-api/shop/gdpr-requests/mutations/delete-gdpr-request.md","filePath":"api/graphql-api/shop/gdpr-requests/mutations/delete-gdpr-request.md","lastUpdated":1787290888000}`),d={name:"api/graphql-api/shop/gdpr-requests/mutations/delete-gdpr-request.md"};function o(n,e,i,u,l,h){return r(),a("div",null,e[0]||(e[0]=[s('<h1 id="delete-a-gdpr-request" tabindex="-1">Delete a GDPR Request <a class="header-anchor" href="#delete-a-gdpr-request" aria-label="Permalink to &quot;Delete a GDPR Request&quot;">​</a></h1><h2 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h2><p>The <code>deleteGdprRequest</code> mutation removes a GDPR data request record owned by the authenticated customer. The mutation returns a snapshot of the deleted request — its <code>_id</code> and a one-time <code>successMessage</code> — so the client can confirm the removal. A customer can only delete their own requests.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>This mutation requires an authenticated customer — send the storefront key and a customer Bearer token. See the <a href="/api/graphql-api/authentication.html">Authentication</a> page.</p><h2 id="gdpr-must-be-enabled" tabindex="-1">GDPR must be enabled <a class="header-anchor" href="#gdpr-must-be-enabled" aria-label="Permalink to &quot;GDPR must be enabled&quot;">​</a></h2><p>If GDPR data requests are disabled in the store&#39;s admin configuration, the mutation fails with the message <strong>&quot;GDPR data requests are disabled. Please enable GDPR from the admin configuration.&quot;</strong> in <code>errors[]</code>. The feature has been turned off on the admin side.</p><h2 id="input-fields" tabindex="-1">Input Fields <a class="header-anchor" href="#input-fields" aria-label="Permalink to &quot;Input Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>ID!</code></td><td>✅ Yes</td><td>The request IRI, e.g. <code>/api/shop/gdpr-requests/12</code>.</td></tr><tr><td><code>clientMutationId</code></td><td><code>String</code></td><td>❌ No</td><td>Arbitrary string echoed back in the payload.</td></tr></tbody></table><h2 id="possible-returns" tabindex="-1">Possible Returns <a class="header-anchor" href="#possible-returns" aria-label="Permalink to &quot;Possible Returns&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>gdprRequest._id</code></td><td><code>Int!</code></td><td>Numeric ID of the deleted request.</td></tr><tr><td><code>gdprRequest.successMessage</code></td><td><code>String</code></td><td>Confirmation message — present on create / revoke / delete results.</td></tr></tbody></table><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/graphql-api/shop/gdpr-requests/mutations/create-gdpr-request.html">Raise a GDPR Request</a></li><li><a href="/api/graphql-api/shop/gdpr-requests/mutations/revoke-gdpr-request.html">Revoke a GDPR Request</a></li><li><a href="/api/graphql-api/shop/gdpr-requests/">GDPR Requests Overview</a></li></ul>',13)]))}const q=t(d,[["render",o]]);export{p as __pageData,q as default};
